// Generates packages/crystal-data/src/records.ts from src/minerals/*.json.
// The JSON files are the source of truth; this inlines them into a module that
// uses no Node-only APIs, so the compiled output runs in browsers and Node.
// Run after editing mineral JSON. The generated file is committed (see the
// registry-operations codegen pattern in scripts/generate-m1-registry.mjs).
import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { join } from 'node:path';

const src = fileURLToPath(new URL('../packages/crystal-data/src/', import.meta.url));
const mineralsDir = join(src, 'minerals');

// Catalog registration order — keep in sync with catalog.ts.
const order = ['fluorite', 'quartz', 'calcite', 'pyrite', 'anatase', 'albite', 'gypsum', 'forsterite', 'beryl'];

const lines = [
    '// GENERATED by scripts/generate-mineral-records.mjs from src/minerals/*.json.',
    '// Do not edit directly — update the JSON and run: node scripts/generate-mineral-records.mjs',
    'import { defineMineral } from "./validate.js";',
    '',
];

for (const name of order) {
    const json = readFileSync(join(mineralsDir, `${name}.json`), 'utf8').trim();
    const constant = name.toUpperCase();
    lines.push(`export const ${constant} = defineMineral(${json});`, '');
}

writeFileSync(join(src, 'records.ts'), lines.join('\n'), 'utf8');
console.log(`Generated ${order.length} mineral records in src/records.ts`);
